import{_ as n,c as a,o as e,ag as l}from"./chunks/framework.CQuhCYrb.js";const b=JSON.parse('{"title":"Self-host-cloudflare-tunnels","description":"","frontmatter":{"title":"Self-host-cloudflare-tunnels"},"headers":[],"relativePath":"infrastructure/self-host-cloudflare-tunnels.md","filePath":"infrastructure/self-host-cloudflare-tunnels.md","lastUpdated":null}'),p={name:"infrastructure/self-host-cloudflare-tunnels.md"};function r(i,s,t,o,c,u){return e(),a("div",null,[...s[0]||(s[0]=[l(`<h1 id="self-host-cloudflare-tunnels" tabindex="-1">Self-host-cloudflare-tunnels <a class="header-anchor" href="#self-host-cloudflare-tunnels" aria-label="Permalink to &quot;Self-host-cloudflare-tunnels&quot;">​</a></h1><h2 id="self-host-with-cloudflare" tabindex="-1">Self-host with Cloudflare <a class="header-anchor" href="#self-host-with-cloudflare" aria-label="Permalink to &quot;Self-host with Cloudflare&quot;">​</a></h2><p><a href="http://dreadytofatroptsdj6io7l3xptbet6onoyno2yv7jicoxknyazubrad.onion%7Csource:" target="_blank" rel="noreferrer">DarkWeb</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="how-to-use-cloudflare" tabindex="-1">How to use Cloudflare <a class="header-anchor" href="#how-to-use-cloudflare" aria-label="Permalink to &quot;How to use Cloudflare&quot;">​</a></h3><h3 id="why-use-cloudflare" tabindex="-1">Why use Cloudflare <a class="header-anchor" href="#why-use-cloudflare" aria-label="Permalink to &quot;Why use Cloudflare&quot;">​</a></h3><h3 id="securing-cloudflare-tunnels" tabindex="-1">Securing Cloudflare Tunnels <a class="header-anchor" href="#securing-cloudflare-tunnels" aria-label="Permalink to &quot;Securing Cloudflare Tunnels&quot;">​</a></h3><p>Many clearnet websites related to DNM, such as link rotators and directories, host on Cloudflare. However, they often fail to take measures to prevent bots from scanning their HTTP services (e.g., Shodan, Censys), which can expose their backend IP addresses.</p><p>To verify if you are affected, you can use:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>telnet YOUR-BACKEND-IP 80</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>or</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>nmap YOUR-BACKEND-IP</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>If you can connect via telnet or Nmap returns your HTTP port, follow the steps below to enhance your security. A simple way to protect yourself is to block any traffic from outside Cloudflare on HTTP port 80 (or whatever port you have proxied with Cloudflare).</p><p><strong>This script does:</strong></p><ul><li><p>Allows SSH traffic (customizable based on your setup)</p></li><li><p>Fetches Cloudflare&#39;s current IPs (both IPv4 and IPv6)</p></li><li><p>Adds iptables rules to allow connections from Cloudflare&#39;s IPs</p></li><li><p>Adds iptables rules to block all connections on HTTP port 80</p></li><li><p>Allows localhost and other essential traffic (these rules can be modified or deleted based on your requirements)</p></li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>CLOUDFLARE_IPV4_URL=&quot;https://www.cloudflare.com/ips-v4&quot;</span></span>
<span class="line"><span>CLOUDFLARE_IPV6_URL=&quot;https://www.cloudflare.com/ips-v6&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>CLOUDFLARE_IPV4=$(curl -s $CLOUDFLARE_IPV4_URL)</span></span>
<span class="line"><span>CLOUDFLARE_IPV6=$(curl -s $CLOUDFLARE_IPV6_URL)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>iptables -F INPUT</span></span>
<span class="line"><span>ip6tables -F INPUT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>iptables -A INPUT -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT</span></span>
<span class="line"><span>ip6tables -A INPUT -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>iptables -A INPUT -p tcp --dport 22 -j ACCEPT</span></span>
<span class="line"><span>ip6tables -A INPUT -p tcp --dport 22 -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>for ip in $CLOUDFLARE_IPV4; do</span></span>
<span class="line"><span>    iptables -A INPUT -p tcp -s $ip --dport 80 -j ACCEPT</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span></span></span>
<span class="line"><span>for ip in $CLOUDFLARE_IPV6; do</span></span>
<span class="line"><span>    ip6tables -A INPUT -p tcp -s $ip --dport 80 -j ACCEPT</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span></span></span>
<span class="line"><span>iptables -A INPUT -p tcp --dport 80 -j DROP</span></span>
<span class="line"><span>ip6tables -A INPUT -p tcp --dport 80 -j DROP</span></span>
<span class="line"><span></span></span>
<span class="line"><span>iptables -A INPUT -i lo -j ACCEPT</span></span>
<span class="line"><span>ip6tables -A INPUT -i lo -j ACCEPT</span></span>
<span class="line"><span>iptables -A INPUT -p icmp --icmp-type 8 -j ACCEPT</span></span>
<span class="line"><span>ip6tables -A INPUT -p ipv6-icmp -j ACCEPT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br></div></div><p><em>Note: If your SSL mode is set to <strong>Full</strong> or <strong>Full Strict</strong>, you will also need to apply similar rules to SSL port 443.</em></p><p>Additionally, if you run a hidden service with Tor, you can further enhance security by allowing traffic only from Tor exit IPs. A separate post will be made for Hidden Services.</p>`,18)])])}const h=n(p,[["render",r]]);export{b as __pageData,h as default};
